//! `crates/al-builtins/src/conv/rows.rs`: the cells of the run matrix of implicit conversions (corpus writer Y31,
//! `tests/al-language/types/lt-y31-conversion-matrix/`, generated by the corpus script `scripts/conversion-matrix/gen_run.py`
//! with the values BC produced), derived from the corpus so that the table cannot drift. Regenerate with `UPDATE_GOLDEN=1`
//! on this test. While the pinned corpus does not hold the folder, the test says so and passes: the committed table is
//! checked once the corpus bump brings it.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

const FOLDER: &str = "tests/al-language/types/lt-y31-conversion-matrix";
const TABLE: &str = "crates/al-builtins/src/conv/rows.rs";

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// The matrix name of a type (a variable, a field `F...` or a literal `Lit...`) as a `Kind` of the table.
fn kind(name: &str) -> &'static str {
    let name = name.strip_prefix('F').filter(|n| kind_opt(n).is_some()).unwrap_or(name);
    kind_opt(name).unwrap_or_else(|| panic!("unknown matrix type name {name}"))
}

fn kind_opt(name: &str) -> Option<&'static str> {
    Some(match name {
        "Integer" | "LitInteger" => "Integer",
        "BigInteger" => "BigInteger",
        "Decimal" | "LitDecimal" => "Decimal",
        // A one-character text literal is a Char where a number is wanted.
        "Char" | "LitChar1" => "Char",
        "Byte" => "Byte",
        "Option" => "Option",
        "Enum" | "EnumImpl" | "LitEnum" => "Enum",
        "Text" | "Text10" | "Text3" | "LitText" | "LitTextEmpty" => "Text",
        "Code10" | "Code3" | "Code250" => "Code",
        "Label" | "LabelLong" => "Label",
        "Guid" => "Guid",
        "Duration" => "Duration",
        "Boolean" => "Boolean",
        "Date" => "Date",
        "Time" => "Time",
        "DateTime" => "DateTime",
        "Variant" => "Variant",
        _ => return None,
    })
}

/// The kind of the value a Variant source of the matrix holds, from the expression assigned to it.
fn held_kind(expr: &str) -> &'static str {
    let e = expr.trim();
    for (helper, k) in [
        ("Util.AsChar(", "Char"),
        ("Util.AsByte(", "Byte"),
        ("Util.AsCode(", "Code"),
        ("Util.AsDuration(", "Duration"),
        ("Util.AsGuid(", "Guid"),
        ("Util.AsOption(", "Option"),
        ("Util.AsText(", "Text"),
        ("CreateDateTime(", "DateTime"),
    ] {
        if e.starts_with(helper) {
            return k;
        }
    }
    let digits = |s: &str| !s.is_empty() && s.trim_start_matches('-').bytes().all(|b| b.is_ascii_digit());
    match e {
        "true" | "false" => "Boolean",
        _ if e.contains("\"::") => "Enum",
        _ if e.ends_with('L') && digits(&e[..e.len() - 1]) => "BigInteger",
        _ if e.ends_with('D') && digits(&e[..e.len() - 1]) => "Date",
        _ if e.ends_with('T') && digits(&e[..e.len() - 1]) => "Time",
        _ if digits(e) => "Integer",
        _ if e.contains('.') && digits(&e.replace('.', "")) => "Decimal",
        _ => panic!("unknown Variant source {e}"),
    }
}

/// An AL string literal (`'...'` with `''` for a quote) at the start of `s`, and the rest after it.
fn al_string(s: &str) -> (String, &str) {
    let mut out = String::new();
    let b = s.strip_prefix('\'').expect("a string literal");
    let mut it = b.char_indices().peekable();
    while let Some((i, c)) = it.next() {
        if c == '\'' {
            if it.peek().is_some_and(|(_, n)| *n == '\'') {
                it.next();
                out.push('\'');
                continue;
            }
            return (out, &b[i + 1..]);
        }
        out.push(c);
    }
    panic!("unterminated string literal in {s}")
}

/// The value, error text and error code BC gave for one observation.
type Parts = (Option<String>, Option<String>, Option<String>);

#[derive(Clone, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum Outcome {
    Value(String),
    Error(String, String),
}

struct Obs {
    family: String,
    /// The value the observation tried (its key without the context).
    tag: String,
    test: String,
    ctx: String,
    /// The source variable's assignments before the observation, by variable name.
    inputs: BTreeMap<String, String>,
    outcome: Outcome,
}

/// Every observation of the `[Test]` procedures of one matrix file.
fn observations(src: &str) -> Vec<Obs> {
    let mut out = Vec::new();
    let mut family = String::new();
    let mut lines = src.lines().peekable();
    while let Some(line) = lines.next() {
        if let Some(rest) = line.strip_prefix("codeunit ") {
            // `codeunit N "LT Y31 <Family> <Source>"`
            let name = rest.split('"').nth(1).unwrap_or_default();
            family = name.split(' ').nth(2).unwrap_or_default().to_string();
            continue;
        }
        if line.trim() != "[Test]" {
            continue;
        }
        let head = lines.next().expect("procedure after [Test]");
        let test = head
            .trim()
            .trim_start_matches("procedure ")
            .trim_end_matches("()")
            .to_string();
        let mut inputs: BTreeMap<String, String> = BTreeMap::new();
        let mut at: BTreeMap<String, BTreeMap<String, String>> = BTreeMap::new();
        let mut expects: Vec<(String, String)> = Vec::new();
        for line in lines.by_ref() {
            if line == "    end;" {
                break;
            }
            let t = line.trim();
            if let Some(rest) = t.strip_prefix("Observer.Expect(") {
                let (key, rest) = al_string(rest);
                let (value, _) = al_string(rest.trim_start_matches(", "));
                expects.push((key, value));
            } else if let Some(pos) = t.find("Observer.ObserveError(") {
                let (key, _) = al_string(&t[pos + "Observer.ObserveError(".len()..]);
                at.insert(key, inputs.clone());
            } else if let Some((lhs, rhs)) = t.split_once(" := ") {
                if !lhs.contains(' ') && rhs.ends_with(';') {
                    inputs.insert(lhs.to_string(), rhs.trim_end_matches(';').to_string());
                }
            }
        }
        let mut by_key: BTreeMap<String, Parts> = BTreeMap::new();
        for (key, value) in expects {
            let (base, part) = key.split_once('|').unwrap_or((&key, ""));
            let e = by_key.entry(base.to_string()).or_default();
            match part {
                "text" => e.1 = Some(value),
                "code" => e.2 = Some(value),
                _ => e.0 = Some(value),
            }
        }
        for (key, (value, text, code)) in by_key {
            let outcome = match value {
                Some(v) => Outcome::Value(v),
                None => Outcome::Error(code.unwrap_or_default(), text.unwrap_or_default()),
            };
            let (ctx, tag) = key.split_once('.').unwrap_or((&key, ""));
            let (ctx, tag) = (ctx.to_string(), tag.to_string());
            out.push(Obs {
                family: family.clone(),
                tag,
                test: test.clone(),
                ctx,
                inputs: at.get(&key).cloned().unwrap_or_default(),
                outcome,
            });
        }
    }
    out
}

/// The table family of an observation, and its (source, target) kinds; `None` for the families the table does not hold.
fn cell(o: &Obs) -> Option<(&'static str, &'static str, &'static str)> {
    let parts: Vec<&str> = o.test.split('_').collect();
    match o.family.as_str() {
        "Cv" => {
            let i = parts.iter().position(|p| *p == "To")?;
            let (src, dst) = (parts[..i].join("_"), parts[i + 1]);
            if src == "Variant" {
                let held = held_kind(o.inputs.get("vVariant")?);
                return Some(("CvVariant", held, kind(dst)));
            }
            Some(("Cv", kind(&src), kind(dst)))
        }
        "Cd" => Some(("Cd", kind(parts[0]), kind(parts[1]))),
        "Cmp" => {
            let fam = match o.ctx.as_str() {
                "eq" | "ne" => "CmpEq",
                "lt" => "CmpLt",
                "in_set" => "CmpIn",
                "case_label" => "CmpCase",
                other => panic!("unknown comparison context {other}"),
            };
            Some((fam, kind(parts[0]), kind(parts[1])))
        }
        "Ar" => {
            let fam = match o.ctx.as_str() {
                "add" => "Add",
                "sub" => "Sub",
                "compound_add" => "AddAssign",
                other => panic!("unknown arithmetic context {other}"),
            };
            Some((fam, kind(parts[0]), kind(parts[1])))
        }
        _ => None,
    }
}

/// Rust string literal.
fn lit(s: &str) -> String {
    format!("{s:?}")
}

/// The cells whose single observations the engine reads (a code page maps the value, no rule covers it).
const POINT_CELLS: &[(&str, &str)] = &[("Char", "Byte"), ("Byte", "Char")];

fn to_rust(files: &[(String, String)]) -> String {
    let mut cells: BTreeMap<(&str, &str, &str), BTreeSet<Outcome>> = BTreeMap::new();
    let mut tried: BTreeMap<(&str, &str, &str), BTreeSet<String>> = BTreeMap::new();
    let mut points: BTreeSet<(&str, &str, String, String)> = BTreeSet::new();
    for (_, text) in files {
        for o in observations(text) {
            let Some(key) = cell(&o) else { continue };
            cells.entry(key).or_default().insert(o.outcome.clone());
            tried.entry(key).or_default().insert(format!("{}/{}", o.test, o.tag));
            if key.0 == "Cv" && POINT_CELLS.contains(&(key.1, key.2)) && o.ctx == "assign" {
                let src = o.test.split("_To_").next().unwrap_or_default();
                if let (Some(input), Outcome::Value(v)) = (o.inputs.get(&format!("v{src}")), &o.outcome) {
                    points.insert((key.1, key.2, input.clone(), v.clone()));
                }
            }
        }
    }
    let mut s = String::new();
    s.push_str("// @generated by crates/al-builtins/tests/conv_matrix_rows.rs from the corpus files\n");
    s.push_str("// Do not edit: UPDATE_GOLDEN=1 cargo test -p al-builtins --test conv_matrix_rows\n");
    for (name, _) in files {
        s.push_str(&format!("// {name}\n"));
    }
    s.push_str("\nuse super::{Family::*, Kind::*, Verdict};\n\n");
    s.push_str(
        "/// Every cell of the run matrix: (family, source, target, what BC gave for every value of the cell).\n",
    );
    s.push_str(
        "#[rustfmt::skip]\npub(super) const CELLS: &[(super::Family, super::Kind, super::Kind, Verdict)] = &[\n",
    );
    for ((fam, src, dst), outcomes) in &cells {
        // One error for every value only counts when more than one value was tried, or when the error is about the type and
        // not the value: a cell tried with one value that overflows (a Variant holding the BigInteger 3000000000,
        // TypeConversion:Overflow) says nothing about the others.
        let several = tried.get(&(*fam, *src, *dst)).is_some_and(|t| t.len() > 1);
        let verdict = match outcomes.iter().collect::<Vec<_>>().as_slice() {
            [Outcome::Error(code, text)] if several || !code.contains("Overflow") => {
                format!("Verdict::Error({}, {})", lit(code), lit(text))
            }
            all if all.iter().all(|o| matches!(o, Outcome::Value(_))) => "Verdict::Values".to_string(),
            _ => "Verdict::Mixed".to_string(),
        };
        s.push_str(&format!("    ({fam}, {src}, {dst}, {verdict}),\n"));
    }
    s.push_str("];\n\n");
    s.push_str("/// Single observations of the cells a code page maps: (source, target, the source as AL, the value BC shows).\n");
    s.push_str("#[rustfmt::skip]\npub(super) const POINTS: &[(super::Kind, super::Kind, &str, &str)] = &[\n");
    for (src, dst, input, v) in &points {
        s.push_str(&format!("    ({src}, {dst}, {}, {}),\n", lit(input), lit(v)));
    }
    s.push_str("];\n");
    s
}

#[test]
fn conv_matrix_rows_are_current() {
    let dir = root().join("corpus").join(FOLDER);
    let Ok(read) = std::fs::read_dir(&dir) else {
        eprintln!("{FOLDER} is not in the pinned corpus yet: {TABLE} is checked after the corpus bump");
        return;
    };
    let mut files: Vec<(String, String)> = read
        .filter_map(|e| {
            let p = e.ok()?.path();
            (p.extension()? == "al").then(|| {
                let name = format!("{FOLDER}/{}", p.file_name().unwrap().to_str().unwrap());
                (name, std::fs::read_to_string(&p).unwrap())
            })
        })
        .collect();
    files.sort();
    let text = to_rust(&files);
    let path = root().join(TABLE);
    if std::env::var_os("UPDATE_GOLDEN").is_some() {
        std::fs::write(&path, &text).unwrap();
    }
    let committed = std::fs::read_to_string(&path).unwrap_or_default();
    assert!(
        committed == text,
        "{TABLE} is stale: run UPDATE_GOLDEN=1 cargo test -p al-builtins --test conv_matrix_rows"
    );
}
